import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Step 1: Input Collection
        System.out.print("Enter Registration ID (int): ");
        int regId = scanner.nextInt();
        scanner.nextLine(); // Clear buffer newline!

        System.out.print("Enter Student Full Name: ");
        String fullName = scanner.nextLine();

        System.out.print("Enter Academic Track: ");
        String track = scanner.next();

        System.out.print("Enter Base Tuition Fee: ");
        double baseFee = scanner.nextDouble();

        System.out.print("Enter Scholarship % (0-100): ");
        double scholarshipPct = scanner.nextDouble();

        System.out.print("Opt for Hostel (true/false): ");
        boolean hasHostel = scanner.nextBoolean();

        // Step 2: Financial Computations
        double scholarshipAmt = baseFee * (scholarshipPct / 100.0);
        double netTuition = baseFee - scholarshipAmt;
        double hostelFee = hasHostel ? 45000.0 : 0.0;
        double subtotal = netTuition + hostelFee;
        double processingFee = subtotal * 0.02; // 2% processing
        double grandTotal = subtotal + processingFee;

        // Step 3: Print Professional Invoice
        System.out.println("\n==================================================");
        System.out.println("          NATIONAL UNIVERSITY ADMISSION           ");
        System.out.println("             OFFICIAL FEE RECEIPT                 ");
        System.out.println("==================================================");
        System.out.printf("Invoice No:   INV-%08d%n", regId);
        System.out.printf("Student Name: %s%n", fullName);
        System.out.printf("Track:        %s%n", track);
        System.out.println("--------------------------------------------------");
        System.out.printf("%-30s : Rs %12.2f%n", "Base Tuition Fee", baseFee);
        System.out.printf("%-30s : Rs -%11.2f%n", "Scholarship Discount (" + scholarshipPct + "%)", scholarshipAmt);
        System.out.printf("%-30s : Rs %12.2f%n", "Net Tuition Fee", netTuition);
        System.out.printf("%-30s : Rs %12.2f%n", "Hostel Accommodation", hostelFee);
        System.out.printf("%-30s : Rs %12.2f%n", "Admin Processing Fee (2%)", processingFee);
        System.out.println("--------------------------------------------------");
        System.out.printf("%-30s : Rs %12.2f%n", "GRAND TOTAL PAYABLE", grandTotal);
        System.out.println("==================================================");
        System.out.println("Status: PAYMENT PENDING | Thank you for enrolling!");

        scanner.close();
    }
}

