import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String name = scanner.nextLine();
        String track = scanner.next();
        double baseFee = scanner.nextDouble();
        double pct = scanner.nextDouble();
        double scholarship = baseFee * (pct / 100.0);
        double net = baseFee - scholarship;
        System.out.println("=== ADMISSION SUMMARY ===");
        System.out.println("Student: " + name);
        System.out.println("Track: " + track);
        System.out.printf("Base Fee: Rs %.2f%n", baseFee);
        System.out.printf("Net Fee:  Rs %.2f%n", net);
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int id = scanner.nextInt();
        scanner.nextLine(); // clear buffer
        String name = scanner.nextLine();
        double consult = scanner.nextDouble();
        double lab = scanner.nextDouble();
        double subtotal = consult + lab;
        double net = subtotal * 0.95;
        System.out.printf("Patient #%06d: %s | Subtotal: Rs %.2f | Net Payable: Rs %.2f%n", id, name, subtotal, net);
        scanner.close();
    }
}

