import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String guest = scanner.nextLine();
        double rate = scanner.nextDouble();
        int nights = scanner.nextInt();
        double food = scanner.nextDouble();
        double roomTotal = rate * nights;
        double roomTax = roomTotal * 0.12;
        double grandTotal = roomTotal + roomTax + food;
        System.out.printf("Guest: %s | Room Stay: Rs %.2f | Food: Rs %.2f | Total: Rs %.2f%n", guest, roomTotal, food, grandTotal);
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String name = scanner.nextLine();
        char tier = scanner.next().charAt(0);
        double fee = scanner.nextDouble();
        int months = scanner.nextInt();
        double total = fee * months;
        System.out.printf("MEMBER: %s [TIER: %c]%n", name, tier);
        System.out.printf("Duration: %d months | Total: Rs %.2f%n", months, total);
        scanner.close();
    }
}
